    stages = execution_plan.get("stages") or []
    row = next((s for s in stages if s.get("ordinal") == retained), None)
    if row is None:
        raise ProviderReturnAdmissionError("PROVIDER_RETURN_STAGE_NOT_IN_PLAN", str(retained))
